    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            size = 0
            while stack:
                y, x = stack.pop()
                size += 1
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
