                        stack.append((ny,nx))
            if size >= 8:
                comps.append((size, v))
    if not comps:
        raise ValueError("No large colored shapes found")
    count = len(comps)
    color = max(comps)[1]
    return [[color for _ in range(count)] for _ in range(count)]
